// Deterministic analysis of the page the extension scraped. No LLM: this is the
// orchestrator leg. Every number below is derived from the payload itself.
const webhook = $input.first().json;
const body = webhook.body || webhook;
const aid = String(body.aid || '').trim();
const triggeredBy = String(body.triggered_by || '');
const payload = (body.payload && typeof body.payload === 'object') ? body.payload : {};
const meta = (body.webhook_data && typeof body.webhook_data === 'object') ? body.webhook_data : {};
const uuidRe = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

if (!uuidRe.test(aid)) {
  return [{ json: { ok: false, error: 'aid (account id) is required and must be a UUID', received_aid: aid } }];
}

// Flatten the scraped object into dotted scalar fields so key-based signals work
// whatever shape the platform extractor produced.
const flat = {};
(function walk(node, prefix) {
  if (node === null || node === undefined) return;
  if (Array.isArray(node)) { node.forEach((v, i) => walk(v, prefix + '[' + i + ']')); return; }
  if (typeof node === 'object') { Object.keys(node).forEach(k => walk(node[k], prefix ? prefix + '.' + k : k)); return; }
  flat[prefix] = String(node);
})(payload, '');

const keys = Object.keys(flat);
const text = JSON.stringify(payload) + ' ' + JSON.stringify(meta);
const has = (re) => keys.some(k => re.test(k) || re.test(flat[k]));
const pick = (names) => { for (const n of names) { const v = flat[n]; if (v) return v; } return ''; };

const email = (text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/) || [''])[0];
const phone = (text.match(/\+?[0-9][0-9().\-\s]{7,}[0-9]/) || [''])[0];
const url = pick(['url', 'data.url', 'page_url', 'meta.url']);
let domain = '';
try { domain = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { domain = ''; }
const title = pick(['title', 'data.title', 'page_title']);
const businessName = pick(['businessName', 'business_name', 'data.businessName', 'data.business_name', 'name']) || title;
const platform = pick(['platform', 'source', 'data.platform']) || 'unknown';
const prompt = pick(['prompt']);

const STOP = new Set(['the','and','for','with','that','this','from','your','you','are','was','were','have','has','had','not','but','all','can','will','our','their','them','they','its','into','out','over','more','most','other','some','such','than','then','there','these','those','when','where','which','while','who','whom','why','how','about','above','after','again','against','because','before','below','between','both','during','each','few','her','here','him','his','itself','just','only','own','same','she','should','too','under','until','very','what','been','being','does','doing','don','http','https','www','com','html','page','site','click','read','view']);

const words = (businessName + ' ' + title + ' ' + keys.map(k => flat[k]).filter(v => v.length > 3 && v.length < 140).join(' '))
  .toLowerCase().replace(/[^a-z0-9\s-]/g, ' ').split(/\s+/)
  .filter(w => w.length > 3 && !STOP.has(w));
const freq = {};
words.forEach(w => { freq[w] = (freq[w] || 0) + 1; });
const keywords = Object.keys(freq).sort((a, b) => freq[b] - freq[a] || a.localeCompare(b)).slice(0, 8);

const signals = {
  has_email: !!email,
  has_phone: !!phone,
  has_address: has(/address|location|city|postal|zip|street/i),
  has_social: has(/facebook|instagram|linkedin|twitter|youtube|tiktok/i),
  has_pricing: has(/price|pricing|cost|rate|plan|fee/i),
  has_reviews: has(/review|rating|stars|testimonial/i),
  has_hours: has(/hours|opening|schedule/i),
  has_contact_name: has(/contact|owner|founder|manager/i)
};

let score = 0;
if (signals.has_email) score += 15;
if (signals.has_phone) score += 15;
if (signals.has_address) score += 10;
if (signals.has_social) score += 10;
if (signals.has_pricing) score += 15;
if (signals.has_reviews) score += 10;
if (businessName) score += 10;
score += Math.min(15, Math.round(keys.length / 3));
score = Math.max(0, Math.min(100, score));

const missing = Object.keys(signals).filter(k => signals[k] === false).map(k => k.replace(/^has_/, ''));
const summary = (businessName || domain || 'Page') + ': ' + keys.length + ' fields parsed, ' +
  keywords.length + ' keywords, contact ' + ((email || phone) ? 'present' : 'missing') +
  ', opportunity score ' + score + '/100' + (missing.length ? ', missing ' + missing.slice(0, 4).join('/') : '');

const analysis = {
  workflow: 'market-intel-analysis',
  business_name: businessName,
  title: title,
  url: url,
  domain: domain,
  platform: platform,
  prompt: prompt,
  contact: { email: email, phone: phone },
  signals: signals,
  keywords: keywords,
  field_count: keys.length,
  opportunity_score: score,
  summary: summary,
  analyzed_at: new Date().toISOString()
};

return [{ json: {
  ok: true,
  aid: aid,
  triggered_by: triggeredBy,
  analysis: analysis,
  log_payload: { analysis: analysis, request: payload, webhook_data: meta, workflow: 'market-intel-analysis' }
} }];
